(* [comment removed for export] *)
Definition wrap_frame (sp : word) (m : mem) (j8 : list byte) (tmp : list cell) (s4v s3v s2v s1v s0v rav : word) : Prop :=
  rw_cells rsegs m (bv_unsigned sp + -80) [CB 8 j8]
  /\ rw_cells rsegs m (bv_unsigned sp + -72) tmp
  /\ rw_cells rsegs m (bv_unsigned sp + -48) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav].

Definition seg2_W (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P + 64, P + 68); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition seg2_post_e (Ef : ecv) (rav sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 in1 : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom rsegs)
    /\ munch (seg2_W lo sp P E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c)
                                              (pc_hlim c - (in1 - p0)) (pc_state c) (pc_f c)) pad7 pad2)
    /\ rw_cells rsegs m' IN [C8 (wz in1)]
    /\ rw_cells rsegs m' E (ErrCodeCells Ef)
    /\ HttpCat m' true /\ XStatics m'.

Definition seg2_post (rav sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 in1 n loc : Z) (E1 : ecv) (m : mem) : machine_state -> Prop :=
  seg2_post_e (psl_ec E1 n (pc_hlim c) loc) rav sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 in1 m.

(* [comment removed for export] *)
Definition seg2_stmt (pc_ret loc : Z) : Prop :=
  forall rv rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 j8 junk : list byte)
    (p0 in1 n : Z) (E1 : ecv) (g : bool),
  wrap_frame sp m j8 [CB 24 junk] s4v s3v s2v s1v s0v rax ->
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells rsegs m IN [C8 (wz in1)] ->
  rw_cells rsegs m E (ErrCodeCells E1) -> ec_ok E1 -> ec_hc E1 ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp + -80) -> lo + 112 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= IN -> IN + 8 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 ->
  (P + 80 <= IN \/ IN + 8 <= P) -> (P + 80 <= E \/ E + 24 <= P) -> (IN + 8 <= E \/ E + 24 <= IN) ->
  p0 <= in1 <= p0 + pc_hlim c -> 0 <= p0 -> in1 < 2^64 -> 0 <= n < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (seg2_post rax sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 in1 n loc E1 m)
    (MS (mkR rv (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz P) (wz IN) a0 a1 a2 a3 a4 a5 a6 a7
              (wz E) (wz n) (wz p0) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc_ret) fc None m (seg_rom rsegs)).

Lemma le4_congr' (a b : word) : bv_unsigned a mod 2^32 = bv_unsigned b mod 2^32 -> le4 a = le4 b.
Proof. intros EQ. unfold le4. rewrite <- (Z_to_le_bytes_mod 4 (bv_unsigned a) 32), <- (Z_to_le_bytes_mod 4 (bv_unsigned b) 32) by (cbn; lia). rewrite EQ. reflexivity. Qed.

Lemma HTTP_CAT_ID_nz : HTTP_CAT_ID <> 0.
Proof. unfold HTTP_CAT_ID. lia. Qed.

