Definition seg2_done_stmt (pc_done : Z) : Prop :=
  forall rax rav sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m0 m : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 j8 : list byte) (x y z : word)
    (p0 in1 n : Z) (Ef : ecv),
  wrap_frame sp m j8 [C8 x; C8 y; C8 z] s4v s3v s2v s1v s0v rav ->
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells rsegs m IN [C8 (wz in1)] ->
  rw_cells rsegs m E (ErrCodeCells Ef) ->
  HttpCat m true -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp + -80) -> lo + 112 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= IN -> IN + 8 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 ->
  (P + 80 <= IN \/ IN + 8 <= P) -> (P + 80 <= E \/ E + 24 <= P) -> (IN + 8 <= E \/ E + 24 <= IN) ->
  p0 <= in1 <= p0 + pc_hlim c -> 0 <= p0 -> in1 < 2^64 ->
  munch (seg2_W lo sp P E) m0 m -> wmono rsegs m0 m -> mem_inv rsegs m ->
  evt rsegs (seg2_post_e Ef rav sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 in1 m0)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz P) (wz IN) a0 a1 a2 a3 a4 a5 a6 a7
              (wz E) (wz n) (wz p0) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc_done) fc None m (seg_rom rsegs)).

Local Ltac seg2_done_script :=
  intros rax rav sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc m0 m P IN E lo c pad7 pad2 j8 x y z p0 in1 n Ef;
  intros FRM PC PCOK IT EC HC XS ST LO IMG PLO PHI ILO IHI ELO EHI DPI DPE DIE IN1 P0 IN1H MU WM MI;
  destruct FRM as (FR0 & TMP & FRhi);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  unfold seg2_W, G_HTTP_CAT in *; unfold ErrCodeCells in EC; unfold ParserCoreCells in PC; unfold wz in *;
  cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  pose proof (munch_refl [(lo, bv_unsigned sp); (P + 64, P + 68)]%Z m) as MU2; pose proof (wmono_refl rsegs m) as WM2;
  (* [comment removed for export] *)
  step; step; step; step; st1;
  (* [comment removed for export] *)
  step; step; step; step; step; step;
  join_frame TMP FRhi (bv_unsigned sp + -72); join_frame FR0 TMP (bv_unsigned sp + -80);
  step; release_frame FR0 ST (bv_unsigned sp); step;
  finish;
  [ (* [comment removed for export] *)
    unfold ParserCoreCells; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz;
    lazymatch goal with |- rw_cells _ ?mx P ?cs =>
      lazymatch goal with PCf : rw_cells _ mx P ?cs0 |- _ =>
        eapply (rw_cells_reshape rsegs mx P cs0 cs PCf); [ exact (proj1 (proj1 PCf)) | cbn [cells_bytes cbytes app] ]
      end
    end;
    repeat first [ reflexivity | apply f_equal2; [ first [reflexivity | apply le4_congr'] | ] ]
  | close_HttpCat_transport HC MU2 WM2
  | close_XStatics XS MU2 WM2 ].
