(* [comment removed for export] *)

Definition seg1_post (pc_inner pc_ret : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E n p0 hl lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 m' j8 junk,
    ms' = MS (mkR (wz pc_ret) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz P) (wz IN)
                  (wz P) (wz IN) (wz (p0 + Z.min n hl)) (wz E) a4 a5 a6 a7 (wz E) (wz n) (wz p0) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz pc_inner) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -80)
    /\ wrap_frame sp m' j8 [CB 24 junk] s4 s3 s2 s1 s0 ra
    /\ (pc_inner = P_BP_INNER_PARSE_START_LINE -> a4 = wz 0).

Definition seg1_stmt (pc_entry pc_inner pc_ret : Z) : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E n p0 lo : Z) (c : pcore) (pad7 pad2 : list byte),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells rsegs m IN [C8 (wz p0)] ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= IN -> IN + 8 <= 2^64 -> 0 <= n < 2^64 -> 0 <= p0 -> p0 + n < 2^64 ->
  0 <= E < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (seg1_post pc_inner pc_ret ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E n p0 (pc_hlim c) lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz n) (wz E) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc_entry) fc None m (seg_rom rsegs)).

Local Ltac seg1_script :=
  intros ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m P IN E n p0 lo c pad7 pad2;
  intros PC PCOK IT ST LO PLO PHI ILO IHI NR P0 PN ER MI;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof (munch_refl [(lo, bv_unsigned sp)]%Z m) as MU; pose proof (wmono_refl rsegs m) as WM;
  destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  unfold P_BP_PARSE_START_LINE, P_BP_PARSE_FIELDS, P_BP_INNER_PARSE_START_LINE, P_BP_INNER_PARSE_FIELDS, PSL_RET, PF_RET in *;
  unfold seg1_post; unfold ParserCoreCells in PC; unfold wz in *;
  cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  carve_frame 80%nat ST;
  (* [comment removed for export] *)
  step; st1; st1; st1; st1; st1; st1; step; step; step;
  (* [comment removed for export] *)
  step; change (zx32 (Z_to_bv 64 (pc_hlim c))) with (zx32 (wz (pc_hlim c))); rewrite zx32_wz by lia; unfold wz;
  step; step; step;
  let K := fresh "K" in
  if_cases K; zify_cond K; rewrite ?unsigned_lit in K by lia;
  [ (* [comment removed for export] *) replace (Z.min n (pc_hlim c)) with n by lia
  | (* [comment removed for export] *) step; replace (Z.min n (pc_hlim c)) with (pc_hlim c) by lia ];
  (* [comment removed for export] *)
  (repeat (lazymatch goal with
           | |- evt _ _ (MS _ _ (Z_to_bv 64 0x3a640) _ _ _ _) => fail
           | |- evt _ _ (MS _ _ (Z_to_bv 64 0x3ad24) _ _ _ _) => fail
           | _ => step end));
  let FRa := fresh "FRa" in let FRhi := fresh "FRhi" in let FR0 := fresh "FR0" in let TMP := fresh "TMP" in
  lazymatch goal with FR : rw_cells _ _ (bv_unsigned sp + -80) [CB 32 ?j32; C8 ?x1; C8 ?x2; C8 ?x3; C8 ?x4; C8 ?x5; C8 ?x6] |- _ =>
    split_frame FR [CB 32 j32] [C8 x1; C8 x2; C8 x3; C8 x4; C8 x5; C8 x6] FRa FRhi;
    destruct (rw_cells_CB_split rsegs _ _ 32 8 j32 FRa ltac:(lia)) as [FR0 TMP]; clear FRa;
    change (32 - 8)%nat with 24%nat in TMP;
    replace (bv_unsigned sp + -80 + Z.of_nat 8) with (bv_unsigned sp + -72) in TMP by lia
  end;
  finish; [ split; [eassumption | split; [eassumption | eassumption]]
